actions.code:
type PreviewCardRootActions = {
    unmount: () => void;
    close: () => void;
};

changeEventDetails.code:
type PreviewCardRootChangeEventDetails = ({
    reason: 'trigger-hover';
    event: MouseEvent;
} | {
    reason: 'trigger-focus';
    event: FocusEvent;
} | {
    reason: 'trigger-press';
    event: MouseEvent | PointerEvent | TouchEvent | KeyboardEvent;
} | {
    reason: 'outside-press';
    event: MouseEvent | PointerEvent | TouchEvent;
} | {
    reason: 'escape-key';
    event: KeyboardEvent;
} | {
    reason: 'imperative-action';
    event: Event;
} | {
    reason: 'none';
    event: Event;
}) & {
    cancel: () => void;
    allowPropagation: () => void;
    isCanceled: boolean;
    isPropagationAllowed: boolean;
    trigger: Element | undefined;
    preventUnmountOnClose: () => void;
};

state.code:
type PreviewCardBackdropState = {
    open: boolean;
    transitionStatus: TransitionStatus;
};

type PreviewCardPositionerState = {
    open: boolean;
    side: Side;
    align: Align;
    anchorHidden: boolean;
    instant: 'dismiss' | 'focus' | undefined;
};

type PreviewCardPopupState = {
    open: boolean;
    side: Side;
    align: Align;
    instant: 'dismiss' | 'focus' | undefined;
    transitionStatus: TransitionStatus;
};

type PreviewCardArrowState = {
    open: boolean;
    side: Side;
    align: Align;
    uncentered: boolean;
};

type PreviewCardViewportState = {
    activationDirection: string | undefined;
    transitioning: boolean;
    instant: 'dismiss' | 'focus' | undefined;
};

